#include <cassert>
#include <cstddef>
#include <iostream>
#include <utility>
#include <vector>
class MinCards {
    // 각 칸은 (카드 값, 이 칸까지의 최솟값)입니다.
    std::vector<std::pair<int,int>> cards_;
public:
    void Push(int value) {
        const int best = cards_.empty() || value < cards_.back().second
            ? value : cards_.back().second;
        cards_.push_back(std::make_pair(value, best));
    }
    bool Pop() {
        if (cards_.empty()) return false;
        cards_.pop_back();
        return true;
    }
    bool Minimum(int& result) const {
        if (cards_.empty()) return false; // 실패 때 result는 그대로입니다.
        result = cards_.back().second;
        return true;
    }
};
int main() {
    MinCards s;
    int result = 99;
    assert(!s.Minimum(result) && result == 99);
    assert(!s.Pop());
    s.Push(3); s.Push(1); s.Push(1); s.Push(2);
    assert(s.Minimum(result) && result == 1);
    assert(s.Pop() && s.Minimum(result) && result == 1);
    assert(s.Pop() && s.Minimum(result) && result == 1);
    assert(s.Pop() && s.Minimum(result) && result == 3);
    assert(s.Pop() && !s.Minimum(result));
    s.Push(-7);
    assert(s.Minimum(result) && result == -7);
    std::cout << "minimum-card checks passed\n";
}
